from fastapi import FastAPI

# Web uygulamamızı başlatıyoruz
app = FastAPI(title='Kampüs Danışma API')

@app.get('/')
def ana_sayfa():
    return {'mesaj': 'Giresun Üniversitesi Kampüs Sistemine Hoş Geldiniz! 🎓'}

@app.get('/selam/{ogrenci_adi}')
def kisisel_selam(ogrenci_adi: str):
    return {
        'durum': 'basarili',
        'mesaj': f'Merhaba {ogrenci_adi}, Giresun Kampüsüne hoş geldin!'
    }

/selam/Ahmet yazıldığında otomatik olarak Ahmet'i yakalar!

@app.get('/kafe/hesapla')
def hesap_yap(cay: int = 0, tost: int = 0):
    toplam = (cay * 15.0) + (tost * 50.0)
    return {
        'cay_adedi': cay,
        'tost_adedi': tost,
        'toplam_tutar_tl': toplam
    }

Tarayıcıda: `/kafe/hesapla?cay=2&tost=1` -> 80.0 TL

@app.get('/yemekhane/bugun')
def menu():
    return {
        'tarih': 'Bugün',
        'corba': 'Ezogelin',
        'ana_yemek': 'Tavuk Sote & Pilav',
        'tatli': 'Meyve',
        'kalori': 750,
        'ogrenci_ucreti': 20.0
    }

@app.get('/not/hesapla')
def not_hesapla(vize: float, final: float):
    ort = (vize * 0.4) + (final * 0.6)
    durum = 'GEÇTİ ✅' if ort >= 50 else 'KALDI ❌'
    return {
        'vize': vize,
        'final': final,
        'ortalama': round(ort, 2),
        'durum': durum
    }

@app.get('/kutuphane/durum')
def kutuphane_durum():
    return {
        'acik_mi': True,
        'toplam_masa': 120,
        'dolu_masa': 45,
        'bos_masa': 75,
        'doluluk_orani': '%37.5'
    }

@app.get('/kafe/fiyat/{urun}')
def urun_fiyati(urun: str):
    fiyatlar = {'cay': 15, 'kahve': 35, 'tost': 50, 'su': 10}
    if urun.lower() in fiyatlar:
        return {'urun': urun, 'fiyat_tl': fiyatlar[urun.lower()]}
    return {'hata': 'Ürün menüde bulunamadı!'}

@app.get('/kare/{sayi}')
def kare_al(sayi: int):
    return {'sonuc': sayi * sayi}

İstek: `/kare/5`
Çıktı: `{'sonuc': 25}`

İstek: `/kare/bes`
Çıktı: `422 Unprocessable Entity` (FastAPI otomatik tip hatası verir!).

